CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),portal text UNIQUE NOT NULL,member_id text UNIQUE NOT NULL,name text NOT NULL,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),bitrix_user_id text NOT NULL, name text NOT NULL, email text, department_id text, position text, role text NOT NULL, is_active boolean NOT NULL DEFAULT true, contractor_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX users_tenant_idx ON users(tenant_id);
CREATE TABLE contractors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL, inn text, contact_data text, status text NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX contractors_tenant_idx ON contractors(tenant_id);
CREATE TABLE objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),external_code text NOT NULL, source text NOT NULL DEFAULT 'MANUAL', name text NOT NULL, address text NOT NULL, customer_name text, organization_name text, project_manager_id uuid NOT NULL, start_date date NOT NULL, planned_finish_date date NOT NULL, actual_finish_date date, contract_value numeric(20,2) NOT NULL CHECK(contract_value>=0), status text NOT NULL DEFAULT 'ACTIVE', health_status text NOT NULL DEFAULT 'GRAY',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX objects_tenant_idx ON objects(tenant_id);
CREATE TABLE object_contractors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),object_id uuid NOT NULL, contractor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX object_contractors_tenant_idx ON object_contractors(tenant_id);
CREATE TABLE work_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),parent_id uuid, name text NOT NULL, code text NOT NULL, sort_order int NOT NULL DEFAULT 0, is_active boolean DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX work_categories_tenant_idx ON work_categories(tenant_id);
CREATE TABLE work_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),category_id uuid NOT NULL, name text NOT NULL, unit text NOT NULL, requires_inspection boolean DEFAULT true, requires_executive_docs boolean DEFAULT true, requires_materials boolean DEFAULT true, is_active boolean DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX work_types_tenant_idx ON work_types(tenant_id);
CREATE TABLE work_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),work_type_id uuid NOT NULL, name text NOT NULL, default_quantity numeric(20,4),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX work_templates_tenant_idx ON work_templates(tenant_id);
CREATE TABLE works(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),object_id uuid NOT NULL, work_type_id uuid NOT NULL, contractor_id uuid NOT NULL, responsible_user_id uuid NOT NULL, name text NOT NULL, unit text NOT NULL, planned_quantity numeric(20,4) NOT NULL CHECK(planned_quantity>0), actual_quantity numeric(20,4) NOT NULL DEFAULT 0 CHECK(actual_quantity>=0), planned_start_date date NOT NULL, planned_finish_date date NOT NULL, actual_start_date date, actual_finish_date date, estimated_cost numeric(20,2) NOT NULL CHECK(estimated_cost>=0), status text NOT NULL DEFAULT 'PLANNED',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX works_tenant_idx ON works(tenant_id);
CREATE TABLE work_dependencies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),predecessor_work_id uuid NOT NULL, successor_work_id uuid NOT NULL, dependency_type text NOT NULL DEFAULT 'FINISH_TO_START' CHECK(dependency_type='FINISH_TO_START'), requires_acceptance boolean DEFAULT true, requires_document boolean DEFAULT false, CHECK(predecessor_work_id<>successor_work_id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX work_dependencies_tenant_idx ON work_dependencies(tenant_id);
CREATE TABLE work_progress(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),object_work_id uuid NOT NULL, quantity_delta numeric(20,4) NOT NULL, total_quantity numeric(20,4) NOT NULL, progress_percent numeric(7,4), reported_at timestamptz NOT NULL DEFAULT now(), reported_by uuid NOT NULL, comment text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX work_progress_tenant_idx ON work_progress(tenant_id);
CREATE TABLE inspections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),object_id uuid NOT NULL, object_work_id uuid NOT NULL, requested_by uuid NOT NULL, requested_at timestamptz DEFAULT now(), inspector_id uuid, status text NOT NULL DEFAULT 'WAITING', inspection_date timestamptz, decision text, comment text, accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX inspections_tenant_idx ON inspections(tenant_id);
CREATE TABLE issues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),inspection_id uuid NOT NULL, title text NOT NULL, description text, severity text NOT NULL CHECK(severity IN ('LOW','MEDIUM','HIGH','CRITICAL')), responsible_user_id uuid NOT NULL, due_date date NOT NULL, status text NOT NULL DEFAULT 'OPEN', resolved_at timestamptz, resolved_by uuid, verified_at timestamptz, verified_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX issues_tenant_idx ON issues(tenant_id);
CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),file_provider text NOT NULL DEFAULT 'LOCAL', external_file_id text, file_name text NOT NULL, mime_type text NOT NULL, content bytea, uploaded_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX attachments_tenant_idx ON attachments(tenant_id);
CREATE TABLE inspection_photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),inspection_id uuid NOT NULL, issue_id uuid, attachment_id uuid NOT NULL, uploaded_by uuid NOT NULL, metadata jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX inspection_photos_tenant_idx ON inspection_photos(tenant_id);
CREATE TABLE materials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL, manufacturer text, brand text, type text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX materials_tenant_idx ON materials(tenant_id);
CREATE TABLE material_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),material_id uuid NOT NULL, batch_number text NOT NULL, supplier text, delivery_date date, object_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX material_batches_tenant_idx ON material_batches(tenant_id);
CREATE TABLE material_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),material_batch_id uuid NOT NULL, type text NOT NULL, number text NOT NULL, valid_from date, valid_until date, file_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX material_documents_tenant_idx ON material_documents(tenant_id);
CREATE TABLE work_materials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),object_work_id uuid NOT NULL, material_batch_id uuid NOT NULL, quantity numeric(20,4) NOT NULL CHECK(quantity>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX work_materials_tenant_idx ON work_materials(tenant_id);
CREATE TABLE executive_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),object_id uuid NOT NULL, object_work_id uuid NOT NULL, type text NOT NULL, number text NOT NULL, document_date date NOT NULL, status text NOT NULL DEFAULT 'DRAFT', file_id uuid, draft_content text, created_by uuid NOT NULL, approved_by uuid, approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX executive_documents_tenant_idx ON executive_documents(tenant_id);
CREATE TABLE executive_packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),object_id uuid NOT NULL, object_work_id uuid NOT NULL, status text NOT NULL DEFAULT 'DRAFT', created_by uuid NOT NULL, completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX executive_packages_tenant_idx ON executive_packages(tenant_id);
CREATE TABLE package_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),package_id uuid NOT NULL, document_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX package_documents_tenant_idx ON package_documents(tenant_id);
CREATE TABLE pto_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),package_id uuid NOT NULL, transferred_by uuid NOT NULL, transferred_at timestamptz DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version int NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX pto_transfers_tenant_idx ON pto_transfers(tenant_id);
