CREATE FUNCTION immutable_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Append-only history'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER progress_immutable BEFORE UPDATE OR DELETE ON work_progress FOR EACH ROW EXECUTE FUNCTION immutable_history();
CREATE TRIGGER closing_immutable BEFORE UPDATE OR DELETE ON financial_closings FOR EACH ROW EXECUTE FUNCTION immutable_history();
